/**
 * Calendar API module — the global Agenda / Calendar manager.
 *
 * Contract: `design/06-calendar/01-analysis.md` §5 ("Backend API").
 *
 * D1 — the calendar store is **global**: the routes are NOT scoped by the
 * active project (the connection still appends `codx_path`, the router simply
 * ignores it) and the projects are only a FILTER of the query.
 * D2 — calendars carry their own scope (`private | team | workspace | system |
 * external`) and the server resolves the ACL per request, so the client never
 * decides who can read a calendar: it renders what the responses contain.
 *
 * Every call returns promises resolved by `API.request` (connection unwraps
 * `data`), so a caller can `try/catch` a 4xx and read `error.response.data`.
 */

const enc = (value) => encodeURIComponent(value == null ? '' : value)

export const calendarModule = (API) => ({
  // ─── Calendars (§5.1) ─────────────────────────────────────────────────────

  calendars: {
    /**
     * Calendars the viewer may see (scope resolution + materialised `system` /
     * `external` entries).
     *
     * @returns {Promise<Array|Object>} `[{...}]` or `{ calendars: [...] }`.
     */
    list() {
      return API.get('/api/calendar/calendars')
    },

    /**
     * Create a calendar.
     *
     * `scope: 'workspace'` requires an admin on the server side.
     *
     * @param {object} payload `{ name, color, scope, audience?, timezone?, default_reminders? }`
     */
    create(payload) {
      return API.post('/api/calendar/calendars', payload)
    },

    /** Partial update (name, color, scope, visible, order, reminders, audience). */
    update(id, payload) {
      return API.put(`/api/calendar/calendars/${enc(id)}`, payload)
    },

    /**
     * Delete a calendar. The server answers 409 `calendar_in_use` when it still
     * holds events and `move_to` was not given, and 409 `read_only_calendar`
     * for `system` calendars.
     *
     * @param {string} id - Calendar id.
     * @param {object} [options] `{ moveTo }` — calendar receiving the events.
     */
    remove(id, { moveTo } = {}) {
      const qs = moveTo ? `?move_to=${enc(moveTo)}` : ''
      return API.delete(`/api/calendar/calendars/${enc(id)}${qs}`)
    },

    /** `{ scope, owner, audience, members[] }` for the sharing panel. */
    share(id) {
      return API.get(`/api/calendar/calendars/${enc(id)}/share`)
    }
  },

  /** Projects the viewer can put events in: `[{ project_id, name, role }]`. */
  projects() {
    return API.get('/api/calendar/projects')
  },

  // ─── Per-user preferences (§5.1) ──────────────────────────────────────────

  prefs: {
    /** Hidden calendars, order and week start of the caller. */
    read() {
      return API.get('/api/calendar/prefs')
    },

    save(prefs) {
      return API.put('/api/calendar/prefs', prefs || {})
    }
  },

  // ─── Events and occurrences (§5.2) ────────────────────────────────────────

  events: {
    /**
     * **The main read.** Recurrences are expanded server-side, so the client
     * receives occurrences ready to render.
     *
     * @param {object} query `{ calendar_ids?, from, to, projects?, q?, sources?, include_hidden? }`
     *   `projects` is OR-ed and `[]`/absent means "every project".
     * @returns {Promise<object>} `{ range, calendars, occurrences, counts, projects, warnings }`
     */
    query(query) {
      return API.post('/api/calendar/events/query', query || {})
    },

    /** Raw event, for the editor (it needs the rule, not the instances). */
    get(id) {
      return API.get(`/api/calendar/events/${enc(id)}`)
    },

    /** Create. `calendar_ids[]` is required by the server. */
    create(payload) {
      return API.post('/api/calendar/events', payload)
    },

    /**
     * Update with optimistic locking.
     *
     * The contract uses `If-Match: <revision>`; the shared connection layer
     * does not expose per-request headers, so the revision travels in the body
     * (`revision`) — the server answers 409 `revision_mismatch` either way.
     *
     * @param {string} id - Event id.
     * @param {object} payload - Event fields.
     * @param {object} [options] `{ revision }`.
     */
    update(id, payload, { revision } = {}) {
      const body = revision == null ? payload : { ...payload, revision }
      return API.put(`/api/calendar/events/${enc(id)}`, body)
    },

    /**
     * Delete (`scope=single|following|all` for a recurring event).
     *
     * @param {string} id - Event id.
     * @param {object} [options] `{ scope }`.
     */
    remove(id, { scope } = {}) {
      const qs = scope ? `?scope=${enc(scope)}` : ''
      return API.delete(`/api/calendar/events/${enc(id)}${qs}`)
    },

    /** Reschedule one reminder of an occurrence (used by the notification centre). */
    snooze(id, { minutes, occurrence_start } = {}) {
      return API.post(`/api/calendar/events/${enc(id)}/snooze`, { minutes, occurrence_start })
    },

    /**
     * Parse a natural-language draft (`"Lunch Ana tom 13:00 1h @Café"`).
     * Nothing is persisted: the editor is filled with the returned draft.
     */
    quick(text) {
      return API.post('/api/calendar/events/quick', { text })
    }
  }
})

/**
 * Date layer of the Agenda / Calendar manager.
 *
 * The SERVER returns occurrences already timezone-shifted and recurrence-
 * expanded (analysis §8.2), so the client never does calendar arithmetic
 * beyond **formatting** and grid placement. What lives here is exactly that:
 * formatters plus the range boundaries sent to `POST /api/calendar/events/query`.
 *
 * Storage / API format is UTC ISO-8601 (`...Z`). `new Date(iso)` therefore
 * yields the right local wall-clock instant to render, and the values of
 * `<input type="datetime-local">` are converted back to UTC on save.
 */

export const MS_DAY = 86400000

/** Monday-first, like the prototype (`design/06-calendar/02-prototype`). */
export const DOW = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
export const DOW_LONG = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
export const MONTHS = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'
]

export const pad2 = (n) => String(n).padStart(2, '0')

/**
 * Parse an API timestamp into a local `Date`.
 * An unparseable / missing value returns `null` instead of `Invalid Date`.
 */
export function parseDate(value) {
  if (!value) return null
  const date = value instanceof Date ? value : new Date(value)
  return Number.isNaN(date.getTime()) ? null : date
}

/** Local `YYYY-MM-DD` key (the bucket id of a day cell). */
export function dateKey(value) {
  const date = parseDate(value)
  if (!date) return ''
  return `${date.getFullYear()}-${pad2(date.getMonth() + 1)}-${pad2(date.getDate())}`
}

/** Key of a `YYYY-MM-DD` string back to the same day at 00:00 local. */
export function dateFromKey(key) {
  if (!key) return null
  const [y, m, d] = String(key).split('-').map(Number)
  if (!y || !m || !d) return null
  return new Date(y, m - 1, d)
}

export function startOfDay(value) {
  const date = parseDate(value) || new Date()
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

export function addDays(value, amount) {
  const date = parseDate(value) || new Date()
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + amount,
    date.getHours(), date.getMinutes(), date.getSeconds())
}

export function addMonths(value, amount) {
  const date = parseDate(value) || new Date()
  return new Date(date.getFullYear(), date.getMonth() + amount, date.getDate())
}

/** Monday 00:00 of the week containing `value`. */
export function startOfWeek(value) {
  const day = startOfDay(value)
  const offset = (day.getDay() + 6) % 7 // 0 = Monday
  return addDays(day, -offset)
}

export function startOfMonth(value) {
  const date = parseDate(value) || new Date()
  return new Date(date.getFullYear(), date.getMonth(), 1)
}

export function sameDay(a, b) {
  const da = parseDate(a)
  const db = parseDate(b)
  if (!da || !db) return false
  return da.getFullYear() === db.getFullYear() &&
    da.getMonth() === db.getMonth() &&
    da.getDate() === db.getDate()
}

export function isToday(value) {
  return sameDay(value, new Date())
}

export function daysBetween(a, b) {
  const da = startOfDay(a)
  const db = startOfDay(b)
  if (!da || !db) return 0
  return Math.round((db.getTime() - da.getTime()) / MS_DAY)
}

/** `09:30` */
export function formatTime(value) {
  const date = parseDate(value)
  return date ? `${pad2(date.getHours())}:${pad2(date.getMinutes())}` : ''
}

/** `09:30 – 10:00` */
export function formatTimeRange(start, end) {
  const from = formatTime(start)
  const to = formatTime(end)
  return from && to ? `${from} – ${to}` : from
}

/** `February 2026` */
export function formatMonthTitle(value) {
  const date = parseDate(value)
  return date ? `${MONTHS[date.getMonth()]} ${date.getFullYear()}` : ''
}

/** `Monday, 9 February 2026` */
export function formatDayLong(value) {
  const date = parseDate(value)
  if (!date) return ''
  return `${DOW_LONG[(date.getDay() + 6) % 7]}, ${date.getDate()} ${MONTHS[date.getMonth()]} ${date.getFullYear()}`
}

/** `Mon 9 Feb` */
export function formatDayShort(value) {
  const date = parseDate(value)
  if (!date) return ''
  return `${DOW[(date.getDay() + 6) % 7]} ${date.getDate()} ${MONTHS[date.getMonth()].slice(0, 3)}`
}

/** UTC ISO-8601 (`...Z`), the transport format of every timestamp. */
export function toIsoDate(value) {
  const date = parseDate(value)
  return date ? date.toISOString() : ''
}

/** `YYYY-MM-DDTHH:mm` for `<input type="datetime-local">` (local wall clock). */
export function toLocalInput(value) {
  const date = parseDate(value)
  if (!date) return ''
  return `${date.getFullYear()}-${pad2(date.getMonth() + 1)}-${pad2(date.getDate())}T${pad2(date.getHours())}:${pad2(date.getMinutes())}`
}

/** Read `<input type="datetime-local">` back into a local `Date`. */
export function fromLocalInput(value) {
  if (!value) return null
  const [dayPart, timePart = '00:00'] = String(value).split('T')
  const [y, m, d] = dayPart.split('-').map(Number)
  const [hh, mm] = timePart.split(':').map(Number)
  if (!y || !m || !d) return null
  return new Date(y, m - 1, d, hh || 0, mm || 0)
}

/** The viewer's IANA timezone, sent with every write so the server can render it. */
export function localTimezone() {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC'
  } catch {
    return 'UTC'
  }
}

/**
 * Query window of a view, in UTC ISO-8601.
 *
 * Month = the full 6×7 grid (the leading/trailing days of the neighbouring
 * months must render), week = 7 days from Monday, day = the cursor day, agenda
 * = 30 days from the cursor.
 *
 * @param {string} view - `month | week | day | agenda`.
 * @param {Date|string} cursor - Any date inside the period.
 * @returns {{ from: string, to: string }}
 */
export function rangeFor(view, cursor) {
  const base = startOfDay(cursor)

  if (view === 'week') {
    const start = startOfWeek(base)
    return { from: toIsoDate(start), to: toIsoDate(addDays(start, 7)) }
  }

  if (view === 'day') {
    return { from: toIsoDate(base), to: toIsoDate(addDays(base, 1)) }
  }

  if (view === 'agenda') {
    return { from: toIsoDate(base), to: toIsoDate(addDays(base, 30)) }
  }

  const gridStart = startOfWeek(startOfMonth(base))
  return { from: toIsoDate(gridStart), to: toIsoDate(addDays(gridStart, 42)) }
}

/** Label of the period shown by the toolbar for a view + cursor. */
export function formatRangeLabel(view, cursor) {
  const base = startOfDay(cursor)

  if (view === 'day') return formatDayLong(base)

  if (view === 'week') {
    const start = startOfWeek(base)
    const end = addDays(start, 6)
    return `${formatDayShort(start)} – ${formatDayShort(end)} ${end.getFullYear()}`
  }

  if (view === 'agenda') {
    return `Agenda · ${formatDayShort(base)} → ${formatDayShort(addDays(base, 29))}`
  }

  return formatMonthTitle(base)
}

import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'
import {
  addDays,
  addMonths,
  dateFromKey,
  dateKey,
  formatRangeLabel,
  parseDate,
  rangeFor,
  startOfDay
} from '@/utils/calendarDate'

/**
 * Agenda / Calendar store (design/06-calendar/01-analysis.md).
 *
 * Follows the project convention: a namespaced Vuex module built with
 * `typed-vuex` (`planning.js`, `orchestration.js`), not a Pinia store — the
 * module is registered in `store/index.js` like every other one.
 *
 * D1 — the store is GLOBAL: `state.calendars` / `state.occurrences` hold the
 * *whole* agenda the viewer may see. Projects never re-scope it; they are a
 * multi-select FILTER (`activeProjects`, OR semantics, empty = All).
 * D2 — calendars are grouped by SCOPE, not by project. The sidebar only ever
 * needs `calendarGroups`.
 *
 * The server expands recurrences and shifts timezones, so this module never
 * computes an occurrence: it asks for a range and keeps the answer.
 */

export const namespaced = true

export const VIEWS = ['month', 'week', 'day', 'agenda']
const DEFAULT_VIEW = 'month'

// How many days a view moves when navigating (‹ / ›). The agenda shows a
// 30-day window (§9.2), so navigating it moves a window, not a single day.
const SHIFT_DAYS = { week: 7, day: 1, agenda: 30 }

// `personal` is not a project: it is the token of the events whose
// `project_id` is null (a private calendar is not a project — §3.1).
export const PERSONAL_PROJECT = 'personal'

export const DEFAULT_PREFS = {
  hidden_calendars: [],
  order: [],
  week_start: 1,
  // Not part of the §5.1 sketch, additive: lets the project filter survive a
  // reload ("persist the choice via prefs").
  active_projects: []
}

/** The API client of the active project (global endpoints, project headers). */
function apiClient() {
  return $storex.projects.activeProject?.$api || $storex.api
}

function errorMessage(error) {
  return error?.response?.data?.detail ||
    error?.response?.data?.message ||
    error?.message ||
    String(error)
}

export const state = () => ({
  // Server data
  calendars: [],
  occurrences: [],
  counts: {},
  warnings: [],
  projects: [],

  // Project filter: [] === All (OR of the selected ids otherwise)
  activeProjects: [],

  // Navigation
  view: DEFAULT_VIEW,
  cursor: dateKey(new Date()),
  range: null,

  // Per-user preferences (hidden calendars, order, week start, filter)
  prefs: { ...DEFAULT_PREFS },
  prefsLoaded: false,

  loading: false,
  error: null,
  loadToken: 0,
  loaded: false
})

// ─── Getters ──────────────────────────────────────────────────────────────────

export const getters = getterTree(state, {
  /** Every calendar the viewer may see, in display order. */
  calendarList: state => {
    const order = state.prefs.order || []
    const weight = cal => {
      const index = order.indexOf(cal.id)
      return index === -1 ? Number.MAX_SAFE_INTEGER : index
    }
    return [...(state.calendars || [])].sort((a, b) => {
      const wa = weight(a)
      const wb = weight(b)
      if (wa !== wb) return wa - wb
      return (a.order ?? 0) - (b.order ?? 0)
    })
  },

  calendarsById: (state, getters) => (id) =>
    (getters.calendarList || []).find(cal => cal.id === id) || null,

  /** Calendars the viewer has not hidden (prefs + the calendar's own flag). */
  visibleCalendarIds: (state, getters) => {
    const hidden = state.prefs.hidden_calendars || []
    return (getters.calendarList || [])
      .filter(cal => cal.visible !== false && !hidden.includes(cal.id))
      .map(cal => cal.id)
  },

  visibleCalendars: (state, getters) => {
    const ids = getters.visibleCalendarIds
    return (getters.calendarList || []).filter(cal => ids.includes(cal.id))
  },

  /** Sidebar sections, grouped by SCOPE (§9.1) — never by project. */
  calendarGroups: (state, getters) => {
    const list = getters.calendarList || []
    const groups = [
      { key: 'private', title: 'My calendars', items: list.filter(cal => cal.scope === 'private') },
      { key: 'shared', title: 'Shared with me', items: list.filter(cal => cal.scope === 'team' || cal.scope === 'workspace') },
      { key: 'system', title: 'codx-junior', items: list.filter(cal => cal.scope === 'system') },
      { key: 'other', title: 'Other', items: list.filter(cal => !['private', 'team', 'workspace', 'system'].includes(cal.scope)) }
    ]
    return groups.filter(group => group.items.length)
  },

  /** Project filter options (plus the `personal` pseudo-project). */
  projectOptions: (state) => {
    const options = (state.projects || [])
      .map(project => ({
        id: project.project_id || project.id || project.codx_path || '',
        name: project.name || project.project_name || project.project_id || '',
        role: project.role || ''
      }))
      .filter(option => option.id)
    if (!options.some(option => option.id === PERSONAL_PROJECT)) {
      options.push({ id: PERSONAL_PROJECT, name: 'Personal · no project', role: '' })
    }
    return options
  },

  isAllProjects: state => !(state.activeProjects || []).length,

  activeView: state => (VIEWS.includes(state.view) ? state.view : DEFAULT_VIEW),

  cursorKey: state => state.cursor,

  cursorDate: state => dateFromKey(state.cursor) || startOfDay(new Date()),

  rangeLabel: (state, getters) => formatRangeLabel(getters.activeView, getters.cursorDate),

  /** Query window of the current view, regenerated from view + cursor. */
  queryRange: (state, getters) => rangeFor(getters.activeView, getters.cursorDate),

  /** Occurrences to render: hidden calendars and the project filter applied. */
  filteredOccurrences: (state, getters) => {
    const visibleIds = getters.visibleCalendarIds || []
    const filtered = (state.occurrences || []).filter(occ => {
      const memberships = occ.calendar_ids || (occ.calendar_id ? [occ.calendar_id] : [])
      if (memberships.length && !memberships.some(id => visibleIds.includes(id))) return false
      if (getters.isAllProjects) return true
      return (state.activeProjects || []).includes(occ.project_id || PERSONAL_PROJECT)
    })
    return filtered.sort((a, b) => {
      if (a.all_day !== b.all_day) return a.all_day ? -1 : 1
      return (parseDate(a.start)?.getTime() || 0) - (parseDate(b.start)?.getTime() || 0)
    })
  },

  /** Occurrences bucketed by local day key — the month grid and agenda read this. */
  occurrencesByDay: (state, getters) => {
    const buckets = {}
    for (const occ of getters.filteredOccurrences) {
      const start = parseDate(occ.start)
      if (!start) continue
      const end = parseDate(occ.end) || start
      // Multi-day (all-day) items appear on every day they cover.
      const span = Math.max(1, Math.ceil((startOfDay(end) - startOfDay(start)) / 86400000) + (occ.all_day ? 0 : 0))
      const days = Number.isFinite(span) && span > 0 ? span : 1
      for (let i = 0; i < days; i++) {
        const key = dateKey(addDays(start, i))
        if (!buckets[key]) buckets[key] = []
        buckets[key].push(occ)
      }
    }
    return buckets
  },

  occurrenceList: state => state.occurrences || [],

  countsByCalendar: state => state.counts?.by_calendar || {},

  filteredCount: (state, getters) => getters.filteredOccurrences.length,

  totalCount: (state, getters) => Number(state.counts?.total ?? (state.occurrences || []).length),

  isLoading: state => state.loading,

  loadError: state => state.error,

  preferences: state => state.prefs
})

// ─── Mutations ────────────────────────────────────────────────────────────────

export const mutations = mutationTree(state, {
  setCalendars(state, calendars) {
    state.calendars = calendars || []
  },

  setOccurrences(state, occurrences) {
    state.occurrences = occurrences || []
  },

  setCounts(state, counts) {
    state.counts = counts || {}
  },

  setWarnings(state, warnings) {
    state.warnings = warnings || []
  },

  setProjects(state, projects) {
    state.projects = projects || []
  },

  setActiveProjects(state, projects) {
    state.activeProjects = projects || []
  },

  setView(state, view) {
    state.view = VIEWS.includes(view) ? view : DEFAULT_VIEW
  },

  setCursor(state, cursor) {
    state.cursor = cursor || dateKey(new Date())
  },

  setRange(state, range) {
    state.range = range || null
  },

  setPrefs(state, prefs) {
    state.prefs = { ...DEFAULT_PREFS, ...(prefs || {}) }
  },

  patchPrefs(state, patch) {
    state.prefs = { ...state.prefs, ...(patch || {}) }
  },

  setPrefsLoaded(state, loaded) {
    state.prefsLoaded = !!loaded
  },

  setLoading(state, loading) {
    state.loading = !!loading
  },

  setError(state, error) {
    state.error = error || null
  },

  setLoaded(state, loaded) {
    state.loaded = !!loaded
  },

  setLoadToken(state, token) {
    state.loadToken = Number(token) || 0
  }
})

// ─── Actions ──────────────────────────────────────────────────────────────────

export const actions = actionTree(
  { state, getters, mutations },
